/* ---------- G5.1: Academy-initiated deposit refund (batch cancelled before start, or admission rejected) ----------
   Raised by whoever cancels/rejects; approved by a Finance Admin (or processed immediately when the Super Admin raises it). */
function depositRefund(name, v, amount, cur, cat, reason) {
  const fins = ADMIN.staff.filter(s => s.roles.includes('Finance Admin') && s.status === 'Active').map(s => s.name), approver = fins.find(n => n !== ADMIN.me.name) || 'Super Administrator', at = now().toISOString();
  if (ADMIN.queue.some(i => i.type === 'Refund' && (i.data || {}).cat === cat && i.related[0].startsWith(name + ' ·'))) return null;
  const it = { id: 'AQ-' + (2100 + ADMIN.queue.length), type: 'Refund', raisedBy: ADMIN.me.name, raised: at, status: 'Pending', first: approver, related: [name + ' · deposit · ' + cat.toLowerCase(), 'f-refunds'], amount, cur, reason: cat + ': ' + reason, notes: [], history: [[ADMIN.me.name, at, 'Raised', reason]], data: { cat, consequence: 'Revoke access', mode: 'Gateway', depV: v, tx: 'Deposit' } };
  ADMIN.queue.unshift(it);
  if (STORE.fin && approver !== 'Super Administrator') STORE.fin.notifs.unshift({ to: approver, t: 'Refund raised awaiting your approval', b: `${it.id} · ${name} · ${money(amount, cur)} (deposit — ${cat.toLowerCase()})`, at, go: 'a-queue.' + it.id, unread: true });
  if (v && STORE.worlds[v] && STORE.worlds[v].admission) STORE.worlds[v].admission.deposit.refund = 'In progress';
  if (isSA()) saApply(it, reason);
  return it;
}
