ACT.lAct = el => {
  const L = learnerById(el.dataset.id), a = el.dataset.a;
  if (a === 'reset') { logA('Learners', L.id, 'Password reset link sent', '—', 'Sent', ''); toast(`Password reset link sent to ${esc(L.email)}.`); return; }
  const lbl = { deactivate: 'Deactivate account', reactivate: 'Reactivate account', archive: 'Archive record', restore: 'Restore to Active' }[a];
  reasonDlg({ title: `${lbl} — ${esc(L.name)}`, ok: lbl, danger: ['deactivate', 'archive'].includes(a), body: a === 'deactivate' ? '<p class="small">The learner is signed out and can\'t sign in. Nothing is deleted.</p>' : a === 'archive' ? `<p class="small">The record becomes read-only and every future access needs a stated purpose. The learner can still sign in read-only; each of their logins is recorded in the audit log as "Archived learner login".</p>` : '',
    onOk: r => {
      const field = ['deactivate', 'reactivate'].includes(a) ? 'acct' : 'rec', val = { deactivate: 'Deactivated', reactivate: 'Active', archive: 'Archived', restore: 'Active' }[a];
      if (L.v) { STORE.acct[L.v] = val === 'Active' ? undefined : val; } else L[field] = val;
      if (a === 'restore') S.ui['arch-' + L.id] = 'Restore';
      logA('Learners', L.id, lbl, field === 'acct' ? L.acct : L.rec, val, r); render(); toast(`${lbl}: done.${L.v ? ' Try signing in as this learner to see the effect.' : ''}`);
    } });
};
