SUBMIT.lContact = f => { if (!guard('Edit contact details')) return; const L = learnerById(f.dataset.id); const nv = { email: $('#lc-e').value, mobile: $('#lc-m').value, address: $('#lc-a').value, postcode: $('#lc-p').value }; if (L.v) { const m = STORE.worlds[L.v].me; Object.assign(m, nv); } else Object.assign(L, nv); logA('Learners', L.id, 'Contact details updated', '—', 'Updated', 'Admin edit'); render(); toast('Contact details saved and logged.'); };
function synthEnrol(L) { return L.courses.map((c, k) => ({ id: 'x' + k, title: c, type: c.includes('Diploma') ? 'NVQ / RQF' : 'Short course', status: L.flags.includes('Discontinued enrolment') && k === 0 ? 'Discontinued' : L.rec === 'Archived' ? 'Completed' : k === 1 ? 'Expired-Incomplete' : 'Active', enrolled: D(-60 - k * 30), start: D(-60 - k * 30), end: D(30 - k * 40), progress: 40 + k * 15, sponsor: L.agency, version: 'Version ' + (2 + k % 2) })); }
